    old && (old.close(), mesh.peers.delete(id));
    codePeer = mesh.add(id, !1);
    await codePeer.setRemote(msg.d);
    let desc = await codePeer.answerComplete();
    let out = await SF.pack({ k: "answer", d: { type: desc.type, sdp: desc.sdp } });
    return "SF1:" + out;
